    "port.mob.gnollguard.desc": "\u69CD\u3068\u76FE\u3092\u6301\u3061\u3001\u515C\u306F\u88AB\u3063\u3066\u3044\u306A\u3044\u3001\u5927\u67C4\u3067\u5C48\u5F37\u305D\u3046\u306A\u30CE\u30FC\u30EB\u3060\u3002\u3053\u306E\u885B\u5175\u306F\u304A\u305D\u3089\u304F\u8A13\u7DF4\u4E2D\u306E\u60AA\u6F22\u3067\u3001\u91CE\u751F\u52D5\u7269\u306E\u4FB5\u5165\u304B\u3089\u9271\u5C71\u3092\u5B88\u308B\u305F\u3081\u306B\u96C7\u308F\u308C\u3066\u3044\u308B\u3088\u3046\u3060\u3002\n\n\u30CE\u30FC\u30EB\u306E\u885B\u5175\u306F\u7247\u624B\u3067\u69CD\u3092\u632F\u308A\u56DE\u305B\u308B\u307B\u3069\u5F37\u3044\u304C\u3001\u3042\u307E\u308A\u4E0A\u624B\u304F\u306F\u4F7F\u3048\u306A\u3044\u3002_\u9060\u8DDD\u96E2\u304B\u3089\u653B\u6483\u3059\u308B\u306B\u306F\u304B\u306A\u308A\u5E83\u3044\u5834\u6240\u304C\u5FC5\u8981\u3067\u3001\u63A5\u8FD1\u3059\u308C\u3070\u30C0\u30E1\u30FC\u30B8\u304C\u304B\u306A\u308A\u5C11\u306A\u304F\u306A\u308B\u3002_",
    "port.mob.gnollguard.desc_armor": "_\u4ED8\u8FD1\u306E\u30CE\u30FC\u30EB\u306E\u5DE5\u5175\u304C\u6301\u3064\u9053\u5177\u306B\u3088\u308A\u3001\u3053\u306E\u885B\u5175\u306B\u5927\u5730\u306E\u93A7\u3092\u4E0E\u3048\u3001\u53D7\u3051\u308B\u30C0\u30E1\u30FC\u30B8\u3092\u5927\u5E45\u306B\u8EFD\u6E1B\u3057\u3066\u3044\u308B\u3002_",
