  "port.spell.holyward.short_desc": "\u0412\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u044F\u0435\u0442 \u0440\u0443\u043D\u0443 \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0437\u0430\u0449\u0438\u0442\u0443 \u0432\u0430\u0448\u0435\u0439 \u0431\u0440\u043E\u043D\u0438",
  "port.buff.illuminated.name": "\u041E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u0435",
  "port.buff.illuminated.desc": "\u042D\u0442\u043E\u0442 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436 \u0441\u0432\u0435\u0442\u0438\u0442\u0441\u044F \u0432 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0435 \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u044F \u0432 \u043D\u0435\u0433\u043E \u043F\u0443\u0442\u0435\u0432\u043E\u0434\u043D\u043E\u0433\u043E \u0441\u0432\u0435\u0442\u0430. \u0425\u043E\u0442\u044F \u0441\u0432\u0435\u0447\u0435\u043D\u0438\u0435 \u043D\u0435 \u043D\u0430\u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0438\u043B\u044C\u043D\u043E\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0441\u0432\u0435\u0442\u0438\u0442\u044C \u043E\u043A\u0440\u0443\u0436\u0430\u044E\u0449\u0435\u0435 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u043E, \u043C\u0430\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u044D\u0444\u0444\u0435\u043A\u0442 \u0437\u043D\u0430\u0447\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043E\u0431\u043B\u0435\u0433\u0447\u0438\u0442 \u043A\u043B\u0438\u0440\u0438\u043A\u0443 \u043D\u0430\u043D\u0435\u0441\u0435\u043D\u0438\u0435 \u0443\u0434\u0430\u0440\u043E\u0432.",
  "port.spell.charge_cost": "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0437\u0430\u0440\u044F\u0434\u0430: {cost}",
  "port.spell.cast_title": "\u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0435",
  "port.talent.satiated_spells.title": "\u041F\u0440\u0435\u0441\u044B\u0449\u0430\u044E\u0449\u0438\u0435 \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F",
  "port.talent.satiated_spells.desc": "_+1:_ \u041F\u0435\u0440\u0435\u043A\u0443\u0441 \u0434\u0430\u0451\u0442 \u041A\u043B\u0438\u0440\u0438\u043A\u0443 _3 \u0449\u0438\u0442\u0430_ \u043F\u0440\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F.\\n\\n_+2:_ \u041F\u0435\u0440\u0435\u043A\u0443\u0441 \u0434\u0430\u0451\u0442 \u041A\u043B\u0438\u0440\u0438\u043A\u0443 _5 \u0449\u0438\u0442\u0430_ \u043F\u0440\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F.",
  "port.talent.holy_intuition.title": "\u0438\u043D\u0442\u0443\u0438\u0446\u0438\u044F \u0441\u0432\u044F\u0442\u043E\u0433\u043E",
  "port.talent.holy_intuition.desc": "_+1:_ \u041A\u043B\u0438\u0440\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0435 _\u0418\u043D\u0442\u0443\u0438\u0446\u0438\u044F \u0441\u0432\u044F\u0442\u043E\u0433\u043E_, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442, \u043F\u0440\u043E\u043A\u043B\u044F\u0442 \u043B\u0438 \u043F\u0440\u0435\u0434\u043C\u0435\u0442, \u0437\u0430 _3 \u0437\u0430\u0440\u044F\u0434\u0430_.\\n\\n_+2:_ \u041A\u043B\u0438\u0440\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0435 _\u0418\u043D\u0442\u0443\u0438\u0446\u0438\u044F \u0441\u0432\u044F\u0442\u043E\u0433\u043E_, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442, \u043F\u0440\u043E\u043A\u043B\u044F\u0442 \u043B\u0438 \u043F\u0440\u0435\u0434\u043C\u0435\u0442, \u0437\u0430 _2 \u0437\u0430\u0440\u044F\u0434\u0430_.",
  "port.talent.searing_light.title": "\u0441\u043B\u0435\u043F\u044F\u0449\u0438\u0439 \u0441\u0432\u0435\u0442",
  "port.talent.searing_light.desc": "_+1:_ \u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0430\u0442\u0430\u043A\u0438 \u041A\u043B\u0438\u0440\u0438\u043A\u0430 \u043F\u043E \u0432\u0440\u0430\u0433\u0430\u043C, \u043E\u0441\u0432\u0435\u0449\u0451\u043D\u043D\u044B\u043C _\u041F\u0443\u0442\u0435\u0432\u043E\u0434\u043D\u044B\u043C \u0421\u0432\u0435\u0442\u043E\u043C_, \u043D\u0430\u043D\u043E\u0441\u044F\u0442 _+3 \u0443\u0440\u043E\u043D\u0430._\\n\\n_+2:_ \u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0430\u0442\u0430\u043A\u0438 \u041A\u043B\u0438\u0440\u0438\u043A\u0430 \u043F\u043E \u0432\u0440\u0430\u0433\u0430\u043C, \u043E\u0441\u0432\u0435\u0449\u0451\u043D\u043D\u044B\u043C _\u041F\u0443\u0442\u0435\u0432\u043E\u0434\u043D\u044B\u043C \u0421\u0432\u0435\u0442\u043E\u043C_, \u043D\u0430\u043D\u043E\u0441\u044F\u0442 _+5 \u0443\u0440\u043E\u043D\u0430._",
  "port.talent.shield_of_light.title": "\u0449\u0438\u0442 \u0441\u0432\u0435\u0442\u0430",
  "port.talent.shield_of_light.desc": "_+1:_ \u041A\u043B\u0438\u0440\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0435 _\u0429\u0438\u0442 \u0441\u0432\u0435\u0442\u0430_, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043D\u0430\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u043E \u0438 \u0434\u0430\u0440\u0443\u0435\u0442 \u0435\u043C\u0443 _2-4 \u0431\u0440\u043E\u043D\u0438_ \u043F\u0440\u043E\u0442\u0438\u0432 \u0446\u0435\u043B\u0438 \u043D\u0430 5 \u0445\u043E\u0434\u043E\u0432 \u0437\u0430 1 \u0437\u0430\u0440\u044F\u0434.\\n\\n_+2:_ \u041A\u043B\u0438\u0440\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0435 _\u0429\u0438\u0442 \u0441\u0432\u0435\u0442\u0430_, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043D\u0430\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u043E \u0438 \u0434\u0430\u0440\u0443\u0435\u0442 \u0435\u043C\u0443 _3-6 \u0431\u0440\u043E\u043D\u0438_ \u043F\u0440\u043E\u0442\u0438\u0432 \u0446\u0435\u043B\u0438 \u043D\u0430 5 \u0445\u043E\u0434\u043E\u0432 \u0437\u0430 1 \u0437\u0430\u0440\u044F\u0434.",
  "port.spell.holyintuition.name": "\u0438\u043D\u0442\u0443\u0438\u0446\u0438\u044F \u0441\u0432\u044F\u0442\u043E\u0433\u043E",
