  "port.class.duelist.blurb": "\u03A0\u03B9\u03BF \u03B5\u03BB\u03B1\u03C6\u03C1\u03CD \u03C3\u03C0\u03B1\u03B8\u03AF \u03B1\u03C0\u03CC \u03C4\u03BF\u03C5 \u03A0\u03BF\u03BB\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE, \u03C3\u03C5\u03BD \u03BA\u03B1\u03C1\u03C6\u03B9\u03AC \u03C1\u03AF\u03C8\u03B7\u03C2.",
  "port.class.cleric.blurb": "\u03A4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C4\u03BF \u03B2\u03B1\u03C1\u03B4\u03BF\u03CD\u03BA\u03B9\u03BF \u03B5\u03AF\u03BD\u03B1\u03B9 40% \u03C0\u03B9\u03BF \u03B5\u03CD\u03C3\u03C4\u03BF\u03C7\u03BF \u03B1\u03C0\u03CC \u03BA\u03AC\u03B8\u03B5 \u03AC\u03BB\u03BB\u03BF \u03B1\u03C1\u03C7\u03B9\u03BA\u03CC \u03CC\u03C0\u03BB\u03BF.",
  "port.class.mage.unlockhint": "\u039E\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03BC\u03B1: \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B5 \u03AD\u03BD\u03B1\u03BD \u03C0\u03AC\u03C0\u03C5\u03C1\u03BF \u03B1\u03BD\u03B1\u03B2\u03AC\u03B8\u03BC\u03B9\u03C3\u03B7\u03C2.",
  "port.class.rogue.unlockhint": "\u039E\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03BC\u03B1: \u03BA\u03AC\u03BD\u03B5 10 \u03B1\u03B9\u03C6\u03BD\u03AF\u03B4\u03B9\u03B5\u03C2 \u03B5\u03C0\u03B9\u03B8\u03AD\u03C3\u03B5\u03B9\u03C2.",
  "port.class.huntress.unlockhint": "\u039E\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03BC\u03B1: \u03C1\u03AF\u03BE\u03B5 10 \u03C6\u03BF\u03C1\u03AD\u03C2.",
  "port.class.duelist.unlockhint": "\u039E\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03BC\u03B1: \u03B1\u03BD\u03AD\u03B2\u03B1\u03C3\u03B5 \u03AD\u03BD\u03B1 \u03CC\u03C0\u03BB\u03BF \u03C3\u03C4\u03BF +2.",
  "port.class.cleric.unlockhint": "\u039E\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03BC\u03B1: \u03BA\u03AD\u03C1\u03B4\u03B9\u03C3\u03B5 \u03AD\u03BD\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9.",
  "port.name.champion.blessed": "\u03B5\u03C5\u03BB\u03BF\u03B3\u03B7\u03BC\u03AD\u03BD\u03BF\u03C2 \u03BC\u03B1\u03C7\u03B7\u03C4\u03AE\u03C2",
