  "port.log.welcome": "{region}, \u03CC\u03C1\u03BF\u03C6\u03BF\u03C2 {depth}. \u0395\u03AF\u03C3\u03B1\u03B9 {hero} \u03BA\u03B1\u03B9 \u03BA\u03C1\u03B1\u03C4\u03AC\u03C2 {weapon}.",
  "port.log.talent": "\u039F \u03B4\u03C1\u03CC\u03BC\u03BF\u03C2 \u03C3\u03BF\u03C5 \u03C7\u03B1\u03C1\u03AC\u03C7\u03C4\u03B7\u03BA\u03B5: {talent}!",
  "port.log.levelup": "\u039A\u03B1\u03BB\u03CE\u03C2 \u03CC\u03C1\u03B9\u03C3\u03B5\u03C2 \u03C3\u03C4\u03BF \u03B5\u03C0\u03AF\u03C0\u03B5\u03B4\u03BF {level}!",
  "port.log.badge": "\u039A\u03AD\u03C1\u03B4\u03B9\u03C3\u03B5\u03C2 \u03C0\u03B1\u03C1\u03AC\u03C3\u03B7\u03BC\u03BF: {badge}!",
  "port.hint.sealedroom": "\u039A\u03B1\u03BC\u03AF\u03B1 \u03C0\u03CC\u03C1\u03C4\u03B1 \u03B4\u03B5\u03BD \u03B2\u03B3\u03AC\u03B6\u03B5\u03B9 \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03B4\u03C9\u03BC\u03AC\u03C4\u03B9\u03BF. \u03A0\u03AC\u03C4\u03B1 F \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C8\u03AC\u03BE\u03B5\u03B9\u03C2 \u03C4\u03BF\u03C5\u03C2 \u03C4\u03BF\u03AF\u03C7\u03BF\u03C5\u03C2 \u03B3\u03B9\u03B1 \u03BA\u03C1\u03C5\u03BC\u03BC\u03AD\u03BD\u03B7.",
  "port.hint.vault": "\u0388\u03BD\u03B1 \u03AE\u03C3\u03C5\u03C7\u03BF \u03B8\u03B7\u03C3\u03B1\u03C5\u03C1\u03BF\u03C6\u03C5\u03BB\u03AC\u03BA\u03B9\u03BF. \u039A\u03AC\u03C4\u03B9 \u03B1\u03BA\u03C4\u03B9\u03BD\u03BF\u03B2\u03CC\u03BB\u03BF \u03C0\u03B5\u03C1\u03B9\u03BC\u03AD\u03BD\u03B5\u03B9 \u03C3\u03C4\u03BF \u03C3\u03BA\u03BF\u03C4\u03AC\u03B4\u03B9.",
  "port.hint.keys": "\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7, F \u03B1\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7, T \u03B5\u03B9\u03B4\u03B9\u03BA\u03AE, E \u03C6\u03B1\u03B3\u03B7\u03C4\u03CC, Q \u03C1\u03CC\u03C6\u03B7\u03BC\u03B1, R \u03B1\u03BD\u03AC\u03B3\u03BD\u03C9\u03C3\u03B7, U \u03B1\u03BD\u03B1\u03B2\u03AC\u03B8\u03BC\u03B9\u03C3\u03B7, O \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03B7, P \u03C6\u03CC\u03C1\u03C4\u03C9\u03C3\u03B7",
  "port.npc.ghost.offer": '\u03A4\u03BF \u03C6\u03AC\u03BD\u03C4\u03B1\u03C3\u03BC\u03B1 \u03C3\u03B5 \u03B9\u03BA\u03B5\u03C4\u03B5\u03CD\u03B5\u03B9: "\u0388\u03BD\u03B1 \u03C0\u03BB\u03AC\u03C3\u03BC\u03B1 \u03C0\u03AE\u03C1\u03B5 \u03C4\u03B1 \u03BA\u03CC\u03BA\u03B1\u03BB\u03AC \u03BC\u03BF\u03C5... \u03C3\u03B5 \u03C0\u03B1\u03C1\u03B1\u03BA\u03B1\u03BB\u03CE, \u03C3\u03BA\u03CC\u03C4\u03C9\u03C3\u03AD \u03C4\u03BF \u03BA\u03B1\u03B9 \u03C6\u03AD\u03C1\u03B5 \u03C4\u03B1 \u03C0\u03AF\u03C3\u03C9."',
  "port.npc.ghost.done": "\u03A4\u03BF \u03C6\u03AC\u03BD\u03C4\u03B1\u03C3\u03BC\u03B1 \u03AD\u03C6\u03C5\u03B3\u03B5. \u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03AC\u03BB\u03BB\u03BF \u03BD\u03B1 \u03B5\u03B9\u03C0\u03C9\u03B8\u03B5\u03AF.",
  "port.npc.ghost.remind": '\u03A4\u03BF \u03C6\u03AC\u03BD\u03C4\u03B1\u03C3\u03BC\u03B1 \u03C8\u03B9\u03B8\u03C5\u03C1\u03AF\u03B6\u03B5\u03B9: "\u03A3\u03B5 \u03C0\u03B1\u03C1\u03B1\u03BA\u03B1\u03BB\u03CE... \u03B2\u03C1\u03B5\u03C2 \u03C4\u03B1 \u03BA\u03CC\u03BA\u03B1\u03BB\u03AC \u03BC\u03BF\u03C5..."',
  "port.npc.ghost.reward": "\u03A4\u03BF \u03C6\u03AC\u03BD\u03C4\u03B1\u03C3\u03BC\u03B1 \u03C3\u03B5 \u03B5\u03C5\u03C7\u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03AF \u03BA\u03B1\u03B9 \u03C3\u03B2\u03AE\u03BD\u03B5\u03B9. \u039D\u03B9\u03CE\u03B8\u03B5\u03B9\u03C2 \u03BB\u03AF\u03B3\u03BF \u03C0\u03B9\u03BF \u03C3\u03BA\u03BB\u03B7\u03C1\u03CC\u03C2: \u03BC\u03AD\u03B3\u03B9\u03C3\u03C4\u03B7 \u03B6\u03C9\u03AE +2.",
  "port.npc.ghost.echo": '\u039C\u03B9\u03B1 \u03C6\u03B1\u03BD\u03C4\u03B1\u03C3\u03BC\u03B1\u03C4\u03B9\u03BA\u03AE \u03C6\u03C9\u03BD\u03AE \u03B1\u03BD\u03C4\u03B7\u03C7\u03B5\u03AF: "\u03A4\u03B1 \u03BA\u03CC\u03BA\u03B1\u03BB\u03AC \u03BC\u03BF\u03C5... \u03B2\u03C1\u03B5\u03C2 \u03BC\u03B5..."',
  "port.npc.blacksmith.offer": '\u03A4\u03BF \u03C4\u03C1\u03BF\u03BB \u03BC\u03BF\u03C5\u03B3\u03BA\u03C1\u03AF\u03B6\u03B5\u03B9: "\u03A6\u03AD\u03C1\u03B5 \u03C0\u03AF\u03C3\u03C9 \u03C4\u03B7\u03BD \u03B1\u03BE\u03AF\u03BD\u03B1 \u03BC\u03BF\u03C5 \u03BC\u03B5 15 \u03C3\u03BA\u03BF\u03C4\u03B5\u03B9\u03BD\u03CC \u03C7\u03C1\u03C5\u03C3\u03CC \u03BA\u03B1\u03B9 \u03B8\u03B1 \u03BE\u03B1\u03BD\u03B1\u03C3\u03C6\u03C5\u03C1\u03B7\u03BB\u03B1\u03C4\u03AE\u03C3\u03C9 \u03C4\u03BF\u03BD \u03B5\u03BE\u03BF\u03C0\u03BB\u03B9\u03C3\u03BC\u03CC \u03C3\u03BF\u03C5."',
  "port.npc.blacksmith.bloodoffer": '\u03A4\u03BF \u03C4\u03C1\u03BF\u03BB \u03B3\u03C1\u03C5\u03BB\u03AF\u03B6\u03B5\u03B9: "\u039B\u03AD\u03C1\u03C9\u03C3\u03B5 \u03C4\u03B7\u03BD \u03B1\u03BE\u03AF\u03BD\u03B1 \u03BC\u03BF\u03C5 \u03BC\u03B5 \u03B1\u03AF\u03BC\u03B1 \u03BD\u03C5\u03C7\u03C4\u03B5\u03C1\u03AF\u03B4\u03B1\u03C2 \u03BA\u03B1\u03B9 \u03B8\u03B1 \u03BE\u03B1\u03BD\u03B1\u03C3\u03C6\u03C5\u03C1\u03B7\u03BB\u03B1\u03C4\u03AE\u03C3\u03C9 \u03C4\u03BF\u03BD \u03B5\u03BE\u03BF\u03C0\u03BB\u03B9\u03C3\u03BC\u03CC \u03C3\u03BF\u03C5."',
  "port.npc.blacksmith.done": '\u03A4\u03BF \u03C4\u03C1\u03BF\u03BB \u03C3\u03B5 \u03B4\u03B9\u03CE\u03C7\u03BD\u03B5\u03B9. "\u039E\u03B5\u03BA\u03BF\u03C5\u03BC\u03C0\u03AF\u03C3\u03BF\u03C5 - \u03C4\u03BF \u03C3\u03B9\u03B4\u03B7\u03C1\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF\u03BF \u03BA\u03C1\u03C5\u03CE\u03BD\u03B5\u03B9."',
  "port.npc.blacksmith.remind": '\u03A4\u03BF \u03C4\u03C1\u03BF\u03BB \u03BC\u03BF\u03C5\u03B3\u03BA\u03C1\u03AF\u03B6\u03B5\u03B9: "\u0391\u03BE\u03AF\u03BD\u03B1 \u03BA\u03B1\u03B9 15 \u03C3\u03BA\u03BF\u03C4\u03B5\u03B9\u03BD\u03CC\u03C2 \u03C7\u03C1\u03C5\u03C3\u03CC\u03C2. \u039A\u03BF\u03C5\u03B2\u03B1\u03BB\u03AC\u03C2 {gold}."',
  "port.npc.blacksmith.bloodremind": '\u03A4\u03BF \u03C4\u03C1\u03BF\u03BB \u03BC\u03BF\u03C5\u03B3\u03BA\u03C1\u03AF\u03B6\u03B5\u03B9: "\u03A7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B5 \u03C4\u03B7\u03BD \u03B1\u03BE\u03AF\u03BD\u03B1 \u03BC\u03BF\u03C5 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C3\u03BA\u03BF\u03C4\u03CE\u03C3\u03B5\u03B9\u03C2 \u03BC\u03B9\u03B1 \u03BD\u03C5\u03C7\u03C4\u03B5\u03C1\u03AF\u03B4\u03B1 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03C6\u03AD\u03C1\u03B5 \u03C4\u03B7\u03BD \u03C0\u03AF\u03C3\u03C9 \u03BB\u03B5\u03C1\u03C9\u03BC\u03AD\u03BD\u03B7 \u03BC\u03B5 \u03B1\u03AF\u03BC\u03B1."',
  "port.log.pickaxeblood": "\u0397 \u03B1\u03BE\u03AF\u03BD\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BB\u03B5\u03C1\u03C9\u03BC\u03AD\u03BD\u03B7 \u03BC\u03B5 \u03B1\u03AF\u03BC\u03B1 \u03BD\u03C5\u03C7\u03C4\u03B5\u03C1\u03AF\u03B4\u03B1\u03C2.",
  "port.npc.blacksmith.reward": "\u03A4\u03BF \u03C3\u03B9\u03B4\u03B7\u03C1\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF\u03BF \u03B2\u03C1\u03C5\u03C7\u03AC\u03C4\u03B1\u03B9! \u039F \u03B5\u03BE\u03BF\u03C0\u03BB\u03B9\u03C3\u03BC\u03CC\u03C2 \u03C3\u03BF\u03C5 \u03BE\u03B1\u03BD\u03B1\u03C3\u03C6\u03C5\u03C1\u03B7\u03BB\u03B1\u03C4\u03AE\u03B8\u03B7\u03BA\u03B5 (\u03CC\u03C0\u03BB\u03BF +{weapon}, \u03C0\u03B1\u03BD\u03BF\u03C0\u03BB\u03AF\u03B1 +{armor}).",
  "port.npc.blacksmith.reforged": "\u03A4\u03BF \u03C3\u03B9\u03B4\u03B7\u03C1\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF\u03BF \u03B2\u03C1\u03C5\u03C7\u03AC\u03C4\u03B1\u03B9! \u03A4\u03BF {item} \u03C3\u03BF\u03C5 \u03BE\u03B1\u03BD\u03B1\u03C3\u03C6\u03C5\u03C1\u03B7\u03BB\u03B1\u03C4\u03AE\u03B8\u03B7\u03BA\u03B5 \u03C3\u03B5 +{level}.",
  "port.npc.imp.offer": '\u03A4\u03BF \u03B4\u03B1\u03B9\u03BC\u03CC\u03BD\u03B9\u03BF \u03C3\u03C6\u03C5\u03C1\u03AF\u03B6\u03B5\u03B9: "\u03A6\u03AD\u03C1\u03B5 \u03BC\u03BF\u03C5 {count} \u03BC\u03AC\u03C1\u03BA\u03B5\u03C2 \u03BD\u03AC\u03BD\u03C9\u03BD \u03B1\u03C0\u03CC \u03C4\u03BF\u03C5\u03C2 {enemy} \u03BA\u03B1\u03B9 \u03C4\u03BF \u03B4\u03B1\u03C7\u03C4\u03C5\u03BB\u03AF\u03B4\u03B9 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03B9\u03BA\u03CC \u03C3\u03BF\u03C5."',
  "port.npc.imp.enemy.monks": "\u03BC\u03BF\u03BD\u03B1\u03C7\u03BF\u03CD\u03C2",
  "port.npc.imp.enemy.golems": "\u03B3\u03BA\u03CC\u03BB\u03B5\u03BC",
  "port.npc.imp.done": "\u03A4\u03BF \u03B4\u03B1\u03B9\u03BC\u03CC\u03BD\u03B9\u03BF \u03AD\u03C6\u03C5\u03B3\u03B5. \u039C\u03CC\u03BD\u03BF \u03B7 \u03BC\u03C5\u03C1\u03C9\u03B4\u03B9\u03AC \u03C4\u03BF\u03C5 \u03B8\u03B5\u03AF\u03BF\u03C5 \u03AD\u03BC\u03B5\u03B9\u03BD\u03B5.",
