  "port.hint.vault": "\uACE0\uC694\uD55C \uAE08\uACE0. \uC5B4\uB460 \uC18D\uC5D0\uC11C \uBE5B\uB098\uB294 \uBB34\uC5B8\uAC00\uAC00 \uAE30\uB2E4\uB9AC\uACE0 \uC788\uB2E4.",
  "port.hint.keys": "\uC774\uB3D9, F \uC218\uC0C9, T \uD2B9\uC218\uD589\uB3D9, E \uBA39\uAE30, Q \uB9C8\uC2DC\uAE30, R \uC77D\uAE30, U \uAC15\uD654, O \uC800\uC7A5, P \uBD88\uB7EC\uC624\uAE30",
  "port.npc.ghost.offer": '\uC720\uB839\uC774 \uC560\uC6D0\uD55C\uB2E4: "\uC5B4\uB5A4 \uAD34\uBB3C\uC774 \uB0B4 \uBF08\uB97C \uAC00\uC838\uAC14\uC5B4... \uBD80\uB514 \uADF8\uB188\uC744 \uC8FD\uC774\uACE0 \uBF08\uB97C \uB3CC\uB824\uC918."',
  "port.npc.ghost.done": "\uC720\uB839\uC740 \uC774\uBBF8 \uB5A0\uB0AC\uB2E4. \uB354 \uD560 \uB9D0\uC774 \uC5C6\uB2E4.",
  "port.npc.ghost.remind": '\uC720\uB839\uC774 \uC18D\uC0AD\uC778\uB2E4: "\uBD80\uB514... \uB0B4 \uBF08\uB97C \uCC3E\uC544\uC918..."',
  "port.npc.ghost.reward": "\uC720\uB839\uC774 \uACE0\uB9C8\uC6CC\uD558\uBA70 \uC0AC\uB77C\uC9C4\uB2E4. \uBAB8\uC774 \uC870\uAE08 \uD2BC\uD2BC\uD574\uC9C4 \uAE30\uBD84\uC774\uB2E4: \uCD5C\uB300 \uCCB4\uB825 +2.",
  "port.npc.ghost.echo": '\uC720\uB839\uC758 \uBAA9\uC18C\uB9AC\uAC00 \uBA54\uC544\uB9AC\uCE5C\uB2E4: "\uB0B4 \uBF08... \uCC3E\uC544\uC918..."',
  "port.npc.blacksmith.offer": '\uD2B8\uB864\uC774 \uC6B0\uB801\uCC28\uAC8C \uB9D0\uD55C\uB2E4: "\uB0B4 \uACE1\uAD2D\uC774\uC640 \uC5B4\uB450\uC6B4 \uAE08 \uC6D0\uC11D 15\uAC1C\uB97C \uAC00\uC838\uC624\uBA74, \uB124 \uC7A5\uBE44\uB97C \uC7AC\uB828\uD574 \uC8FC\uC9C0."',
