var bossScene = readFileSync(join(process.cwd(), "src/scenes/dungeon/bosses/bossLogic.ts"), "utf8");
var blobSim = readFileSync(join(process.cwd(), "src/simulation/environmentalBlobs.ts"), "utf8");
check(
  "a blast breaks open plain chests (flag cleared, contents stay) and leaves locked/crystal/shop heaps untouched",
  dropScene.includes("if (ground.chest === 'normal' && !ground.forSale) {") && dropScene.includes("ground.chest = undefined;") && dropScene.includes("if (ground.chest !== undefined || ground.forSale) return false;")
);
check(
  "a landed flask hard-presses its cell before shattering (trap/grass/plant/web)",
  dropScene.includes("this.pressCellFromFlask(at.x, at.y);") && envScene.includes("pressCellFromFlask(this: DungeonScene, x: number, y: number)")
);
check(
  "a revealed trap still fires for the hero (Java hard press ignores reveal state)",
  envScene.includes("if (this.secrets.isSecret(x, y)) this.secrets.discover(x, y);") && !envScene.includes("if (!this.secrets.isSecret(x, y)) return;")
);
check(
  "an unattended trap trigger seeds its positional halves and spends (darts/grim only spend)",
  envScene.includes("triggerUnattendedTrapAt(this: DungeonScene, x: number, y: number)") && envScene.includes("else if (kind === 'explosive') {") && envScene.includes("if (kind !== 'gateway') this.spentTrapCells.add(cell);")
);
check(
  "mobs trample high grass on step (terrain falls, naturalism-0 loot, no hero bits)",
  envScene.includes("trampleMobGrass(this: DungeonScene, monster: Creature)") && envScene.includes("heroClass: 'mob',") && bossScene.includes("if (moved) this.trampleMobGrass(creature);")
);
check(
  "a chasm landing presses its cell (trap, grass, plant) before the Cripple, like heroLand",
  hazardScene.includes("this.triggerTrapAt(this.hero.x, this.hero.y);") && hazardScene.includes("this.trampleHighGrass(this.hero.x, this.hero.y);") && hazardScene.includes("this.triggerPortedPlantAt(this.hero.x, this.hero.y);") && hazardScene.includes("if (this.hero.hp <= 0) return;")
);
check(
  "confusion gas prolongs vertigo (a longer live clock survives instead of resetting to 2)",
  blobSim.includes("if ((target.buffs?.['vertigo'] ?? 0) < 2) context.addBuff(target, 'vertigo', 2);")
);
if (failed > 0) {
  console.error(`${failed} drop/throw check(s) failed`);
  process.exit(1);
}
console.log("verifyDropThrow: OK");
